            "부작용 프로필은 프로페시아와 동일해요. 임상시험 1년차 기준으로 성욕 감퇴(1.8%), 발기부전(1.3%), 사정량 감소(1.2%)가 보고되었어요. 2~4년차에는 위약군과의 차이가 더 줄어들어서 장기 복용할수록 성기능 부작용 발생률이 낮아지는 경향이에요. 대부분 복용을 중단하면 회복돼요.\n\n드물게 유방 통증·비대(여성형 유방증), 우울감, 피부 알레르기 반응 등이 나타날 수 있어요. 유방에 멍울이 느껴지거나 통증이 있으면 즉시 복용을 중단하고 의사에게 알려야 해요. 우울증이나 기분 변화가 지속되는 경우에도 전문의와 상담하는 게 좋아요.\n\nPSA(전립선특이항원) 수치를 약 50% 낮추므로, 전립선암 검사를 받을 때 반드시 피나스테리드 복용 사실을 알려야 정확한 진단이 가능해요. 알리지 않으면 PSA가 실제보다 낮게 나와서 암 진단이 지연될 위험이 있어요. 과민반응(두드러기, 혈관부종, 발진)이 나타나면 즉시 중단하고 응급처치를 받으세요.",
