          "가장 흔한 건 바른 자리의 국소 반응이에요. 식약처 허가사항에 가려움, 인설, 홍반, 발적, 피부염, 피부건조, 모낭염, 작열감 같은 국소 자극이 적혀 있어요. 처음 바를 때 두피가 따끔하거나 비듬처럼 일어나는 경우가 여기 해당해요. 탈락, 피부 농양, 여드름, 지루, 습진처럼 피부 쪽 반응도 같이 보고돼 있어요.\n\n다모증도 보고돼요. 허가 문서상 바른 부위 외에 털이 날 수 있어요. 특히 여성은 안면 털이 자랄 수 있어서, 바른 뒤 손을 씻고 베개에 닿지 않게 완전히 말린 뒤 눕는 게 좋아요.\n\n드물지만 전신 반응도 있어요. 식약처 자료에는 흉통, 혈압변화, 맥박변화, 심계항진, 어지럼, 두통, 실신이 나와요. 미녹시딜이 혈관에 작용하는 성분이라 그래요. 이런 증상이 보이면 즉시 사용을 멈추고 의사나 약사와 상의하세요.",
