            "이 대목이 중요해요. 식약처 허가 문서에 포함된 4년 임상시험(PLESS) 자료 기준으로 살펴볼게요. 이 약으로 치료받은 1,524명 중 3.7%(57명)가 성기능 관련 이상반응으로 치료를 중단했고, 위약군은 2.1%(32명)였어요.\n\n1년차에 위약보다 높은 빈도로 나타난 이상반응 중 발현율 1% 이상인 항목은 이래요. 발기부전이 이 약 8.1%, 위약 3.7%였고, 성욕감퇴는 6.4% 대 3.4%, 사정액 감소는 3.7% 대 0.8%였어요. 2~4년차에는 발기부전·성욕감퇴·사정장애에서 투여군 간 유의한 차이가 없어졌어요.\n\n시판 후 보고에서 추가로 알려진 이상반응도 있어요. 면역계에서 가려움, 두드러기, 혈관부종 같은 과민반응이 있었고, 정신계에서는 우울증, 자살생각, 불안이 보고됐죠. 고환통, 혈정액증, 남성 불임과 정액 질 저하, 남성 유방암도 사례가 있어요. 기분 변화나 성기능 변화가 생기면 의사에게 알리는 게 맞아요.",
