            "큐엘파마가 만든 피나스테리드 1mg 성분의 전문의약품이에요. 품목 분류는 모발용제(발모, 탈모, 염모, 양모제)로 식약처에 등록돼 있고, 품목번호는 202100729예요. 식약처 허가 적응증은 성인남성(만 18~41세)의 남성형 탈모증(안드로겐 탈모증) 치료거든요.\n\n같은 성분의 오리지널인 프로페시아와 동일한 피나스테리드 1mg을 담은 제네릭이라, 처방 현장에서 비용 부담을 줄이려는 선택지로 자주 쓰여요. 다만 적응증이 성인 남성으로 한정돼 있다는 점은 짚어둘게요. 소아나 여성에게는 투여하지 않도록 허가 문서가 못 박고 있어요. 탈모 관리용으로 처방받을 때도 본인의 모발 상태에 맞는지 의사 판단이 먼저예요.",
