            "하나씩 살펴볼게요. 식약처 식약처 등록 정보에 수록된 4년간 위약대조 임상시험(PLESS) 결과를 보면, 1년차에서 발기부전 8.1%(위약 3.7%), 성욕감퇴 6.4%(위약 3.4%), 사정액감소 3.7%(위약 0.8%)가 보고됐어요. 복용 2~4년차에는 발기부전 5.1%, 성욕감퇴 2.6%로 위약군과 차이가 줄어들었어요.\n\n시간이 지나면서 발생률이 낮아지는 경향이 있어요. 드물게 유방비대, 유방압통, 발진도 나타날 수 있어요.\n\n주의해야 할 경고 항목이 3가지 있죠. 첫째, 이 약은 소아 또는 여성에게 투여하지 않아요. 둘째, 기분변형과 우울증 보고가 있어요. 허가 기준에 따르면 피나스테리드 5mg을 투여한 환자에서 우울한 기분, 우울증, 자살생각을 포함한 기분변형이 보고됐어요. 정신과적 증상이 나타나면 의료전문가와 상담해야 해요. 셋째, 전립선특이항원(PSA) 수치를 약 50% 감소시키기 때문에 전립선암 스크리닝 시 복용 중임을 의사에게 반드시 알려야 해요.",
