            "3개월 이상 복용한 뒤부터 치료 효과를 기대할 수 있어요. 식약처 허가 용법에 '일반적으로 3개월 이상 복용해야 치료효과를 볼 수 있다'고 명시돼 있는 기준이에요.\n\n알로펙정의 주성분 피나스테리드는 5α-환원효소 2형을 억제해 테스토스테론이 DHT로 전환되는 걸 막아요. 이 과정이 모낭 위축을 늦추고 탈모 진행을 억제하는 방식이에요. 허가 기준 임상시험(945명 대상)에서 성기능 관련 이상반응으로 중단한 비율은 1.2%였어요.\n\n효과가 유지되려면 지속 복용이 전제예요. 복용을 중단하면 12개월 내에 치료 효과가 사라진다고 허가 문서에 명확히 적혀 있어요. 3개월이라는 기간을 알고 시작하면, 중간에 흔들리는 일이 줄어요.",
