            "삼성두타스테리드정 30정의 기준가는 22,000원이에요. 1일 1정 기준으로 30정이 한 달분이고, 1정당 733원이고요. 한 달 복용 비용은 기준가 22,000원 수준이죠.\n\n두타스테리드 0.5mg 제네릭 그룹은 국내에 45개 품목이 있고, 삼성두타스테리드정은 그 중 27위예요. 그룹 내 1정당 가격 범위는 200원~1,267원으로 폭이 넓어요. 가장 저렴한 제품(휴메리나정, 케이두타다트정, 유힐릭스정)은 30정 6,000원, 1정당 200원이에요. 삼성두타스테리드정의 733원은 그보다 높은 수준이죠.\n\n장기 복용 약이라 월 비용이 누적되는 구조예요. 1정당 가격 차이가 크면 매달 비용 차이도 상당해요. 같은 성분·같은 용량 제품들 사이에서 가격 비교가 합리적인 선택 기준이 돼요. 현재 구매 가능한 최저가는 아래 버튼에서 확인할 수 있어요.",
